const MapMongolia = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapMongoliaContent element={element} />
    </ElementWrapper>
  );
};

export const MapMongoliaPresent = ({ element }) => {
  return <MapMongoliaContent element={element} />;
};

